			DEVICE ZXSPECTRUMNEXT		; for SAVENEX at the end
			MMU 0 5, 0			; #0000-#BFFF: the Next's 8K pages 0-5 (its 16K banks 0, 1, 2: NTC pages 0, 1, 2 - 20261116-7, it was banks 8, 9, 10)
